import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S04/S04E01.html","title":"S04E01 The One with the Jellyfish","lang":"zh-CN","frontmatter":{"title":"S04E01 The One with the Jellyfish","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":74},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":31.18,"words":9353},"filePathRelative":"语言/英语/Friends老友记/S04/S04E01.md"}`),l={name:`S04E01.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=t(`<h1 id="the-one-with-the-jellyfish" tabindex="-1"><a class="header-anchor" href="#the-one-with-the-jellyfish"><span>The One with the Jellyfish</span></a></h1><blockquote><p><em>带水母的那个</em></p></blockquote><p>The One With The Jellyfish</p><blockquote><p>带水母的那个</p></blockquote><p><strong>Written by: Wil Calhoun</strong></p><blockquote><p>作者：威尔·卡尔霍恩</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote>`,8),r(p,{src:`/audio/friends/S04/S04E01/001.mp3`}),c[1]||=t(` <strong>Joey Tribbiani:</strong> (lying on a beach towel, recapping what happened in the last episode) Okay, so we went to the beach, because Phoebe found out about this lady who knew her mom and dad, and I don’t really know what happened with that.<blockquote><p>（躺在沙滩浴巾上，回顾上一集发生的事情）好吧，我们去了海滩，因为菲比发现了一位认识她父母的女士，我真的不知道发生了什么。</p></blockquote><p>[cut to Phoebe Sr.’s house, from the last episode]</p><blockquote><p>[切换到老菲比的家，从上一集开始]</p></blockquote><p>Phoebe Sr.: (to Phoebe) I’m your mother.</p><blockquote><p>老<strong>菲比·布菲：</strong>（对菲比）我是你妈妈。</p></blockquote>`,8),r(p,{src:`/audio/friends/S04/S04E01/002.mp3`}),c[2]||=i(),c[3]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[4]||=i(` Ehh?`,-1),c[5]||=a(`blockquote`,null,[a(`p`,null,`嗯？`)],-1),c[6]||=a(`p`,null,`[cut to Monica opening the door of the beach house, with Chandler trying to pick her up for a date.]`,-1),c[7]||=a(`blockquote`,null,[a(`p`,null,`[镜头切换到莫妮卡打开海滩小屋的门，钱德勒试图接她去约会。]`)],-1),r(p,{src:`/audio/friends/S04/S04E01/003.mp3`}),c[8]||=i(),c[9]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[10]||=i(` (voice-over) Oh, and then Monica joked that she wouldn’t go out with a guy like Chandler...`,-1),c[11]||=a(`blockquote`,null,[a(`p`,null,`（画外音）哦，然后莫妮卡开玩笑说她不会和钱德勒这样的男人出去。。。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/004.mp3`}),c[12]||=i(),c[13]||=a(`strong`,null,`Chandler Bing:`,-1),c[14]||=i(` (to Monica) (in a funny voice) Hi there. (Monica turns her head away in disgust)`,-1),c[15]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）（用滑稽的声音）你好。（莫妮卡厌恶地把头转过去）`)],-1),r(p,{src:`/audio/friends/S04/S04E01/005.mp3`}),c[16]||=i(),c[17]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[18]||=i(` (voice-over) ...and he couldn’t let it go, and... I don’t really know what happened with that either.`,-1),c[19]||=a(`blockquote`,null,[a(`p`,null,`（画外音）……他不能放手，而且。。。我也不知道发生了什么。`)],-1),c[20]||=a(`p`,null,`[cut to a montage of scenes involving Bonnie, Ross, and Rachel from the last episode.]`,-1),c[21]||=a(`blockquote`,null,[a(`p`,null,`[切换到上一集邦妮、罗斯和瑞秋的蒙太奇场景。]`)],-1),r(p,{src:`/audio/friends/S04/S04E01/006.mp3`}),c[22]||=i(),c[23]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[24]||=i(` (voice-over) Oh-oh! And then Ross’s new girlfriend, Bonnie, shows up and Rachel convinced her to save her head. And then Ross and Rachel kiss, and now Ross has to choose between Rachel and the bald girl and I don’t know what happened there either...`,-1),c[25]||=a(`blockquote`,null,[a(`p`,null,`（画外音）哦！然后罗斯的新女友邦妮出现了，瑞秋说服她救了自己的头。然后罗斯和瑞秋接吻，现在罗斯不得不在瑞秋和秃头女孩之间做出选择，我也不知道那里发生了什么。。。`)],-1),c[26]||=a(`p`,null,`[cut back to Joey on the beach towel]`,-1),c[27]||=a(`blockquote`,null,[a(`p`,null,`[回到乔伊在沙滩浴巾上]`)],-1),r(p,{src:`/audio/friends/S04/S04E01/007.mp3`}),c[28]||=i(),c[29]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[30]||=i(` Y'know what, hold on, let me go get Chandler. (gets up and leaves.)`,-1),c[31]||=a(`blockquote`,null,[a(`p`,null,`你知道吗，等一下，让我去找钱德勒。（起身离开。）`)],-1),c[32]||=a(`hr`,null,null,-1),c[33]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The beach house, it’s the same scene from the end of last year, with Ross in front of the two doors of Rachel’s and Bonnie’s rooms, trying to decide which door to choose. He finally chooses the one his right and goes in.`)],-1),c[34]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`海滩别墅，与去年年底的场景相同，罗斯站在瑞秋和邦妮房间的两扇门前，试图决定选择哪扇门。他最终选择了他右边的那扇门，然后走了进去。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/008.mp3`}),c[35]||=i(),c[36]||=a(`strong`,null,`Ross Geller:`,-1),c[37]||=i(` (surprised) Hi!`,-1),c[38]||=a(`blockquote`,null,[a(`p`,null,`（惊讶地）嗨！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/009.mp3`}),c[39]||=i(),c[40]||=a(`strong`,null,`Rachel and Bonnie:`,-1),c[41]||=i(` Hi!`,-1),c[42]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/010.mp3`}),c[43]||=i(),c[44]||=a(`strong`,null,`Bonnie:`,-1),c[45]||=i(` Rachel was just helping me out. My head got all sunburned.`,-1),c[46]||=a(`blockquote`,null,[a(`p`,null,`瑞秋只是在帮我。我的头被晒伤了。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/011.mp3`}),c[47]||=i(),c[48]||=a(`strong`,null,`Ross Geller:`,-1),c[49]||=i(` Awww.`,-1),c[50]||=a(`blockquote`,null,[a(`p`,null,`啊。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/012.mp3`}),c[51]||=i(),c[52]||=a(`strong`,null,`Bonnie:`,-1),c[53]||=i(` (to Rachel) Thanks a million.`,-1),c[54]||=a(`blockquote`,null,[a(`p`,null,`（对瑞秋）非常感谢。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/013.mp3`}),c[55]||=i(),c[56]||=a(`strong`,null,`Rachel Green:`,-1),c[57]||=i(` Oh, you’re welcome a million.`,-1),c[58]||=a(`blockquote`,null,[a(`p`,null,`哦，非常欢迎你。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/014.mp3`}),c[59]||=i(),c[60]||=a(`strong`,null,`Bonnie:`,-1),c[61]||=i(` (getting up and leaving) (to Ross) Okay, I’ll see you in our room.`,-1),c[62]||=a(`blockquote`,null,[a(`p`,null,`（起身离开）（对罗斯）好的，我们房间见。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/015.mp3`}),c[63]||=i(),c[64]||=a(`strong`,null,`Ross Geller:`,-1),c[65]||=i(` Yeah. (closes the door, and goes over and kisses Rachel.)`,-1),c[66]||=a(`blockquote`,null,[a(`p`,null,`是的。（关上门，走过去亲吻瑞秋。）`)],-1),r(p,{src:`/audio/friends/S04/S04E01/016.mp3`}),c[67]||=i(),c[68]||=a(`strong`,null,`Rachel Green:`,-1),c[69]||=i(` (softly) Oh my God.`,-1),c[70]||=a(`blockquote`,null,[a(`p`,null,`（轻轻地）哦，我的天啊。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/017.mp3`}),c[71]||=i(),c[72]||=a(`strong`,null,`Ross Geller:`,-1),c[73]||=i(` I know.`,-1),c[74]||=a(`blockquote`,null,[a(`p`,null,`我知道。`)],-1),c[75]||=a(`p`,null,[a(`em`,null,`(They both kiss again and fall onto the bed.)`)],-1),c[76]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们两人再次接吻，然后摔倒在床上。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/018.mp3`}),c[77]||=i(),c[78]||=a(`strong`,null,`Ross Geller:`,-1),c[79]||=i(` (stopping suddenly and getting up) Okay, I gotta go.`,-1),c[80]||=a(`blockquote`,null,[a(`p`,null,`（突然停下来站起来）好了，我得走了。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/019.mp3`}),c[81]||=i(),c[82]||=a(`strong`,null,`Rachel Green:`,-1),c[83]||=i(` Whoa! What?! Why?!`,-1),c[84]||=a(`blockquote`,null,[a(`p`,null,`哇！什么？！为什么？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/020.mp3`}),c[85]||=i(),c[86]||=a(`strong`,null,`Ross Geller:`,-1),c[87]||=i(` Well, I-I gotta go break up with Bonnie.`,-1),c[88]||=a(`blockquote`,null,[a(`p`,null,`好吧，我要和邦妮分手了。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/021.mp3`}),c[89]||=i(),c[90]||=a(`strong`,null,`Rachel Green:`,-1),c[91]||=i(` Here?! Now?!`,-1),c[92]||=a(`blockquote`,null,[a(`p`,null,`这里？！现在？！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/022.mp3`}),c[93]||=i(),c[94]||=a(`strong`,null,`Ross Geller:`,-1),c[95]||=i(` Well, yeah. I can’t-I can’t stay here all night, and if I go in there she’s-she’s gonna wanna... do stuff.`,-1),c[96]||=a(`blockquote`,null,[a(`p`,null,`嗯，是的。我不能，我不能整晚呆在这里，如果我进去，她会想。。。做事。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/023.mp3`}),c[97]||=i(),c[98]||=a(`strong`,null,`Rachel Green:`,-1),c[99]||=i(` Well, can’t you tell her that you are not in the mood?`,-1),c[100]||=a(`blockquote`,null,[a(`p`,null,`你不能告诉她你没心情吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/024.mp3`}),c[101]||=i(),c[102]||=a(`strong`,null,`Ross Geller:`,-1),c[103]||=i(` No, she likes that. Yeah. Faking sleep doesn’t work either, I can’t tell you how many mornings I woke up with her...`,-1),c[104]||=a(`blockquote`,null,[a(`p`,null,`不，她喜欢那样。是 啊假装睡觉也不管用，我不能告诉你有多少个早上我和她一起醒来。。。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/025.mp3`}),c[105]||=i(),c[106]||=a(`strong`,null,`Rachel Green:`,-1),c[107]||=i(` (interrupting) Whoa-ho.`,-1),c[108]||=a(`blockquote`,null,[a(`p`,null,`（打断）哇哦。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/026.mp3`}),c[109]||=i(),c[110]||=a(`strong`,null,`Ross Geller:`,-1),c[111]||=i(` Whoa-oh, okay! Yeah, why am I telling you that?`,-1),c[112]||=a(`blockquote`,null,[a(`p`,null,`哇哦，好的！是啊，为什么我要告诉你？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/027.mp3`}),c[113]||=i(),c[114]||=a(`strong`,null,`Rachel Green:`,-1),c[115]||=i(` I don’t know.`,-1),c[116]||=a(`blockquote`,null,[a(`p`,null,`我不知道。`)],-1),c[117]||=a(`p`,null,[a(`em`,null,`(they kiss again)`)],-1),c[118]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们又接吻了）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/028.mp3`}),c[119]||=i(),c[120]||=a(`strong`,null,`Ross Geller:`,-1),c[121]||=i(` Yeah, yeah. (opens the door) It wasn’t every morning.`,-1),c[122]||=a(`blockquote`,null,[a(`p`,null,`是的，是的。（打开门）不是每天早上。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/029.mp3`}),c[123]||=i(),c[124]||=a(`strong`,null,`Rachel Green:`,-1),c[125]||=i(` Oh, making it worse!`,-1),c[126]||=a(`blockquote`,null,[a(`p`,null,`哦，更糟了！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/030.mp3`}),c[127]||=t(` <strong>Ross Geller:</strong> Okay.<blockquote><p>好的。</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Phoebe Sr.’s house, it’s right after she told Phoebe that she’s her birth mother.</em></p><blockquote><p>🎬 <em>老菲比的房子，就在她告诉菲比她是她的生母之后。</em></p></blockquote><p>Phoebe Sr.: So I guess you’d like to know how it all happened.</p><blockquote><p>老<strong>菲比·布菲：</strong>所以我想你想知道这一切是怎么发生的。</p></blockquote>`,11),r(p,{src:`/audio/friends/S04/S04E01/031.mp3`}),c[128]||=i(),c[129]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[130]||=i(` I-I mean I, well I think I can figure it out. I guess y'know I was born, and everyone started lying their asses off!`,-1),c[131]||=a(`blockquote`,null,[a(`p`,null,`我是说，我想我能弄明白。我想你知道我出生了，每个人都开始撒谎！`)],-1),c[132]||=a(`p`,null,`Phoebe Sr.: Noo! No! It wasn’t like that I... Remember how I told you how Lily, Frank, and I we were, we were close. Well, we were, we were very close.`,-1),c[133]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`不！不不是那样的我。。。还记得我告诉过你莉莉、弗兰克和我我们是多么的亲密吗。嗯，我们，我们非常接近。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/032.mp3`}),c[134]||=i(),c[135]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[136]||=i(` How close?`,-1),c[137]||=a(`blockquote`,null,[a(`p`,null,`有多近？`)],-1),c[138]||=a(`p`,null,`Phoebe Sr.: Well, the-the three of us we were, kind of umm, a couple.`,-1),c[139]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`嗯，我们三个人，嗯，算是一对。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/033.mp3`}),c[140]||=i(),c[141]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[142]||=i(` I don’t even know how that would work!`,-1),c[143]||=a(`blockquote`,null,[a(`p`,null,`我甚至不知道那会是怎样的！`)],-1),c[144]||=a(`p`,null,`Phoebe Sr.: Well, we were...`,-1),c[145]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`嗯，我们是。。。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/034.mp3`}),c[146]||=i(),c[147]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[148]||=i(` (interrupting) I’m not asking!`,-1),c[149]||=a(`blockquote`,null,[a(`p`,null,`（打断一下）我不是在问！`)],-1),c[150]||=a(`p`,null,`Phoebe Sr.: Well, any how, some how I got pregnant, and, and I was scared. I was stupid and sellfish, and I was 18 years old. I mean, you remember what it’s like to be eighteen years old?`,-1),c[151]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`不管怎样，我是怎么怀孕的，我很害怕。我很愚蠢，而且还卖鱼，那时我18岁。我是说，你还记得十八岁是什么感觉吗？`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/035.mp3`}),c[152]||=i(),c[153]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[154]||=i(` Yeah. Let’s see, my had Mom killed herself, and my Dad had run off, and I was living in a Gremlin with a guy named Cindy who talked to his hand.`,-1),c[155]||=a(`blockquote`,null,[a(`p`,null,`是的。让我想想，我妈妈自杀了，我爸爸跑掉了，我和一个叫辛迪的人住在一个小精灵里，他和他的手说话。`)],-1),c[156]||=a(`p`,null,`Phoebe Sr.: Well, I’m so sorry. I thought I was leaving you with the best parents in the world, I didn’t even hear about your Mom and Dad til a couple of years ago, and by then you were already grown up. I don’t know, you’re here, and I would, I would really, I would like to get to know you.`,-1),c[157]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`我很抱歉。我以为我要把你留给世界上最好的父母，直到几年前我才听说你的父母，那时你已经长大了。我不知道，你在这里，我会，我真的，我想了解你。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/036.mp3`}),c[158]||=i(),c[159]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[160]||=i(` Yeah, well, everybody does! I’m a really cool person. And y'know you had 29 years to find that out, but you didn’t even try! Y'know what, you walked out on me, and I’m just, I’m gonna do the same thing to you.`,-1),c[161]||=a(`blockquote`,null,[a(`p`,null,`是啊，每个人都这样！我是个很酷的人。你知道你花了29年的时间才发现这一点，但你甚至都没试过！你知道吗，你抛弃了我，我只是，我会对你做同样的事。`)],-1),c[162]||=a(`p`,null,`Phoebe Sr.: Wait!`,-1),c[163]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`等等！`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/037.mp3`}),c[164]||=i(),c[165]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[166]||=i(` I don’t ever want to see you again!`,-1),c[167]||=a(`blockquote`,null,[a(`p`,null,`我再也不想见到你了！`)],-1),c[168]||=a(`p`,null,[a(`em`,null,`(She walks out and slams the door.)`)],-1),c[169]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（她走出去，砰地关上门。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/038.mp3`}),c[170]||=i(),c[171]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[172]||=i(` (walking back in with her hand over her eyes.) Umm, where’s my purse?`,-1),c[173]||=a(`blockquote`,null,[a(`p`,null,`（用手捂着眼睛走回去）嗯，我的钱包呢？`)],-1),c[174]||=a(`hr`,null,null,-1),c[175]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The beach house, Joey and Chandler are sitting at the dinner table, Monica is looking in the fridge.`)],-1),c[176]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`海滩小屋，乔伊和钱德勒坐在餐桌旁，莫妮卡在冰箱里看。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/039.mp3`}),c[177]||=i(),c[178]||=a(`strong`,null,`Monica Geller:`,-1),c[179]||=i(` (closing the fridge in disgust) Shoot! We’re out of soda.`,-1),c[180]||=a(`blockquote`,null,[a(`p`,null,`（厌恶地关上冰箱）开枪！苏打水用完了。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/040.mp3`}),c[181]||=i(),c[182]||=a(`strong`,null,`Chandler Bing:`,-1),c[183]||=i(` (jumping up) Oh, I’ll go out and get you some.`,-1),c[184]||=a(`blockquote`,null,[a(`p`,null,`（跳起来）哦，我出去给你拿一些。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/041.mp3`}),c[185]||=i(),c[186]||=a(`strong`,null,`Monica Geller:`,-1),c[187]||=i(` Really?!`,-1),c[188]||=a(`blockquote`,null,[a(`p`,null,`真的吗？！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/042.mp3`}),c[189]||=i(),c[190]||=a(`strong`,null,`Chandler Bing:`,-1),c[191]||=i(` Nope! Because I’m not your boyfriend. (to Phoebe, who’s entering) Hey Pheebs, how did it go?`,-1),c[192]||=a(`blockquote`,null,[a(`p`,null,`不！因为我不是你的男朋友。（对正在进来的菲比）嘿，菲比，怎么样？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/043.mp3`}),c[193]||=i(),c[194]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[195]||=i(` Well, umm, my Mom’s friend, Phoebe, is actually my birth Mom.`,-1),c[196]||=a(`blockquote`,null,[a(`p`,null,`嗯，嗯，我妈妈的朋友菲比实际上是我的生母。`)],-1),c[197]||=a(`p`,null,[a(`em`,null,`(The gang is shocked.)`)],-1),c[198]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（这伙人震惊了。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/044.mp3`}),c[199]||=i(),c[200]||=a(`strong`,null,`Chandler Bing:`,-1),c[201]||=i(` I found a dried up seashores.`,-1),c[202]||=a(`blockquote`,null,[a(`p`,null,`我发现了一个干涸的海岸。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/045.mp3`}),c[203]||=i(),c[204]||=a(`strong`,null,`Monica Geller:`,-1),c[205]||=i(` Sweety, what are you talking about?`,-1),c[206]||=a(`blockquote`,null,[a(`p`,null,`亲爱的，你在说什么？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/046.mp3`}),c[207]||=i(),c[208]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[209]||=i(` Oh, my new Mom, who-who’s a big, fat abandoner! (starts to go upstairs)`,-1),c[210]||=a(`blockquote`,null,[a(`p`,null,`哦，我的新妈妈，她是个又大又胖的弃儿！（开始上楼）`)],-1),r(p,{src:`/audio/friends/S04/S04E01/047.mp3`}),c[211]||=i(),c[212]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[213]||=i(` Whoa, wait, Pheebs, wait a second! Don’t you wanna stay here and talk about it?`,-1),c[214]||=a(`blockquote`,null,[a(`p`,null,`哇，等等，菲比，等等！你不想呆在这里谈谈吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/048.mp3`}),c[215]||=i(),c[216]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[217]||=i(` No. I’m just, I wanna, I need to be alone.`,-1),c[218]||=a(`blockquote`,null,[a(`p`,null,`不，我只是，我想，我需要一个人。`)],-1),c[219]||=a(`p`,null,[a(`em`,null,`(She starts to go upstairs.)`)],-1),c[220]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（她开始上楼。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/049.mp3`}),c[221]||=i(),c[222]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[223]||=i(` (turning around, insistently) Monica!`,-1),c[224]||=a(`blockquote`,null,[a(`p`,null,`（转身，坚持地）莫妮卡！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/050.mp3`}),c[225]||=i(),c[226]||=a(`strong`,null,`Monica Geller:`,-1),c[227]||=i(` Oh.`,-1),c[228]||=a(`blockquote`,null,[a(`p`,null,`哦。`)],-1),c[229]||=a(`hr`,null,null,-1),c[230]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The beach house, Rachel’s bedroom. She is finishing up writing something as Ross walks through the door.`)],-1),c[231]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`海滩小屋，瑞秋的卧室。罗斯进门时，她正在写完一些东西。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/051.mp3`}),c[232]||=i(),c[233]||=a(`strong`,null,`Ross Geller:`,-1),c[234]||=i(` It’s over.`,-1),c[235]||=a(`blockquote`,null,[a(`p`,null,`结束了。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/052.mp3`}),c[236]||=i(),c[237]||=a(`strong`,null,`Rachel Green:`,-1),c[238]||=i(` Oh, was it awful?`,-1),c[239]||=a(`blockquote`,null,[a(`p`,null,`哦，糟糕吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/053.mp3`}),c[240]||=i(),c[241]||=a(`strong`,null,`Ross Geller:`,-1),c[242]||=i(` Well, it was loong. I didn’t even realise how late it was, until I noticed the 5 o’clock shadow on her head. (They both start to laugh, then stop themselves quickly.) Anyway, she didn’t want to stay. I called a cab; she just left.`,-1),c[243]||=a(`blockquote`,null,[a(`p`,null,`是龙。我甚至没有意识到有多晚了，直到我注意到她头上5点钟的影子。（他们俩都笑了起来，然后很快停了下来。）不管怎样，她不想留下来。我叫了辆出租车；她刚离开。`)],-1),c[244]||=a(`p`,null,[a(`em`,null,`(They kiss.)`)],-1),c[245]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们接吻。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/054.mp3`}),c[246]||=i(),c[247]||=a(`strong`,null,`Rachel Green:`,-1),c[248]||=i(` I wrote you a letter.`,-1),c[249]||=a(`blockquote`,null,[a(`p`,null,`我给你写了封信。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/055.mp3`}),c[250]||=i(),c[251]||=a(`strong`,null,`Ross Geller:`,-1),c[252]||=i(` Ohh! Thank you! I like mail. (He goes to kiss her again, but she turns away.)`,-1),c[253]||=a(`blockquote`,null,[a(`p`,null,`哦！非常感谢。我喜欢邮寄。（他又去吻她，但她转过身去。）`)],-1),r(p,{src:`/audio/friends/S04/S04E01/056.mp3`}),c[254]||=i(),c[255]||=a(`strong`,null,`Rachel Green:`,-1),c[256]||=i(` (handing him the letter) It’s just some things I’ve been thinking about. Some things about us, and before we can even think about the two of us getting back together, I just need to know how you feel about this stuff.`,-1),c[257]||=a(`blockquote`,null,[a(`p`,null,`（把信递给他）这只是我一直在想的一些事情。关于我们的一些事情，在我们考虑我们两人重聚之前，我只想知道你对这些事情的感受。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/057.mp3`}),c[258]||=i(),c[259]||=a(`strong`,null,`Ross Geller:`,-1),c[260]||=i(` Okay. (He leans in to kiss her again, but she leans back preventing him from making contact.) Wow, it’s-it’s 5:30 in the morning. (Rachel laughs) So, I’d better get cracking on this baby.`,-1),c[261]||=a(`blockquote`,null,[a(`p`,null,`好的。（他弯下身来再次吻她，但她向后倾，阻止他接触。）哇，现在是早上5:30。（瑞秋笑着）所以，我最好开始对付这个孩子。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/058.mp3`}),c[262]||=i(),c[263]||=a(`strong`,null,`Rachel Green:`,-1),c[264]||=i(` Well, I’ll be waiting for you, just come up when you’re done.`,-1),c[265]||=a(`blockquote`,null,[a(`p`,null,`好吧，我会等你的，等你做完就上来。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/059.mp3`}),c[266]||=i(),c[267]||=a(`strong`,null,`Ross Geller:`,-1),c[268]||=i(` Okay, I’ll be up in, (looks at the letter) 18 pages. Front and back. Very exciting.`,-1),c[269]||=a(`blockquote`,null,[a(`p`,null,`好的，我会在（看信）18页上。正面和背面。非常激动人心。`)],-1),c[270]||=a(`hr`,null,null,-1),c[271]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The beach house, the next morning. Ross is passed out on the kitchen counter. He wakes up with a start and has one of the pages of the letter stuck to his face.`)],-1),c[272]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`海滩小屋，第二天早上。罗斯昏倒在厨房柜台上。他惊醒后，脸上贴着一页信。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/060.mp3`}),c[273]||=i(),c[274]||=a(`strong`,null,`Ross Geller:`,-1),c[275]||=i(` Oh. (looks at his watch) Oh-oh. (takes a drink of coffee and resumes reading the letter)`,-1),c[276]||=a(`blockquote`,null,[a(`p`,null,`哦。（看了看手表）噢。（喝了杯咖啡，然后继续读这封信）`)],-1),r(p,{src:`/audio/friends/S04/S04E01/061.mp3`}),c[277]||=i(),c[278]||=a(`strong`,null,`Rachel Green:`,-1),c[279]||=i(` (coming down the stairs) Hey! (Ross jumps up, and quickly puts the letter back together, pretending like he has just finished it.) What happened to you? Why didn’t you come up?`,-1),c[280]||=a(`blockquote`,null,[a(`p`,null,`（下楼）嘿！（罗斯跳起来，很快地把信放回原处，假装他刚写完。）你怎么了？你为什么不上来？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/062.mp3`}),c[281]||=i(),c[282]||=a(`strong`,null,`Ross Geller:`,-1),c[283]||=i(` Done!`,-1),c[284]||=a(`blockquote`,null,[a(`p`,null,`好了！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/063.mp3`}),c[285]||=i(),c[286]||=a(`strong`,null,`Rachel Green:`,-1),c[287]||=i(` You just finished?`,-1),c[288]||=a(`blockquote`,null,[a(`p`,null,`你刚做完？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/064.mp3`}),c[289]||=i(),c[290]||=a(`strong`,null,`Ross Geller:`,-1),c[291]||=i(` Well, I wanted to be thorough. I mean this-this is clearly very, very important to you, to us! And so I wanted to read every word carefully, twice!`,-1),c[292]||=a(`blockquote`,null,[a(`p`,null,`嗯，我想彻底检查一下。我的意思是，这显然对你，对我们非常非常重要！所以我想把每一个字都仔细读两遍！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/065.mp3`}),c[293]||=i(),c[294]||=a(`strong`,null,`Rachel Green:`,-1),c[295]||=i(` So umm, does it?`,-1),c[296]||=a(`blockquote`,null,[a(`p`,null,`嗯，是吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/066.mp3`}),c[297]||=i(),c[298]||=a(`strong`,null,`Ross Geller:`,-1),c[299]||=i(` I’m sorry.`,-1),c[300]||=a(`blockquote`,null,[a(`p`,null,`对不起。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/067.mp3`}),c[301]||=i(),c[302]||=a(`strong`,null,`Rachel Green:`,-1),c[303]||=i(` Does it?`,-1),c[304]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/068.mp3`}),c[305]||=i(),c[306]||=a(`strong`,null,`Ross Geller:`,-1),c[307]||=i(` Does it? Does it? Yeah, I wanted to give that whole ‘Does it?’ part just another glance.`,-1),c[308]||=a(`blockquote`,null,[a(`p`,null,`是吗？是吗？是的，我想再看一眼整个“是吗”部分。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/069.mp3`}),c[309]||=i(),c[310]||=a(`strong`,null,`Rachel Green:`,-1),c[311]||=i(` What are you talking about, Ross, you just said that you read it twice! Look, y'know what, either it does or it doesn’t, and if you have to even think about it...`,-1),c[312]||=a(`blockquote`,null,[a(`p`,null,`你在说什么，罗斯，你刚才说你读了两遍！听着，你知道吗，要么有，要么没有，如果你想一想。。。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/070.mp3`}),c[313]||=i(),c[314]||=a(`strong`,null,`Ross Geller:`,-1),c[315]||=i(` (interrupting) No, Rach, no. I don’t, I don’t, I don’t have to think about it, in fact, I’ve decided, I’ve decided that, that it.......does.`,-1),c[316]||=a(`blockquote`,null,[a(`p`,null,`（打断）不，瑞秋，不。我不，我不，我不需要去想它，事实上，我已经决定，我已经决定，它……是的。`)],-1),c[317]||=a(`p`,null,[a(`em`,null,`(Rachel stands there for a moment, starting to cry. Then gasps and runs over and hugs him. While hugging her, Ross tries to find the ‘Does it?’ part in the letter.)`)],-1),c[318]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（瑞秋站在那里片刻，开始哭泣。然后喘息着跑过去拥抱他。罗斯在拥抱她时，试图找到信中的“成功”部分。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/071.mp3`}),c[319]||=i(),c[320]||=a(`strong`,null,`Rachel Green:`,-1),c[321]||=i(` Are you sure?`,-1),c[322]||=a(`blockquote`,null,[a(`p`,null,`你确定吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/072.mp3`}),c[323]||=i(),c[324]||=a(`strong`,null,`Ross Geller:`,-1),c[325]||=i(` Oh, sure! I’m sure.`,-1),c[326]||=a(`blockquote`,null,[a(`p`,null,`哦，当然！我敢肯定。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/073.mp3`}),c[327]||=i(),c[328]||=a(`strong`,null,`Rachel Green:`,-1),c[329]||=i(` I know. (Hugs him more violently this time and pushes him back away from the letter.)`,-1),c[330]||=a(`blockquote`,null,[a(`p`,null,`我知道。（这次更猛烈地拥抱他，把他推开。）`)],-1),c[331]||=a(`hr`,null,null,-1),c[332]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The beach. Chandler and Monica are out getting some sun.`)],-1),c[333]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`海滩。钱德勒和莫妮卡出去晒太阳。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/074.mp3`}),c[334]||=i(),c[335]||=a(`strong`,null,`Chandler Bing:`,-1),c[336]||=i(` All right, there’s a nuclear holocaust, I’m the last man on Earth. Would you go out with me?`,-1),c[337]||=a(`blockquote`,null,[a(`p`,null,`好吧，这是一场核大屠杀，我是地球上最后一个人。你愿意和我一起出去吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/075.mp3`}),c[338]||=i(),c[339]||=a(`strong`,null,`Monica Geller:`,-1),c[340]||=i(` Ennnh.`,-1),c[341]||=a(`blockquote`,null,[a(`p`,null,`恩。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/076.mp3`}),c[342]||=i(),c[343]||=a(`strong`,null,`Chandler Bing:`,-1),c[344]||=i(` I’ve got canned goods.`,-1),c[345]||=a(`blockquote`,null,[a(`p`,null,`我有罐头食品。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/077.mp3`}),c[346]||=i(),c[347]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[348]||=i(` (jumping up in a hole that he is digging, he is shoulder deep) Hey, you guys! Take a look at this! (Chandler and Monica jump up and go over to the hole.) Check this baby out, dug me a hole!`,-1),c[349]||=a(`blockquote`,null,[a(`p`,null,`（跳到他正在挖的洞里，他有肩膀深）嘿，你们这些家伙！看看这个！（钱德勒和莫妮卡跳起来，走向那个洞。）看看这个孩子，给我挖了个洞！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/078.mp3`}),c[350]||=i(),c[351]||=a(`strong`,null,`Chandler Bing:`,-1),c[352]||=i(` Excellent hole, Joe.`,-1),c[353]||=a(`blockquote`,null,[a(`p`,null,`很棒的洞，乔。`)],-1),c[354]||=a(`p`,null,[a(`em`,null,`(A wave crashes on the beach and partially fills up his hole.)`)],-1),c[355]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（一股巨浪冲击着海滩，部分填满了他的洞穴。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/079.mp3`}),c[356]||=i(),c[357]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[358]||=i(` Oh no! No!! My hole!!`,-1),c[359]||=a(`blockquote`,null,[a(`p`,null,`哦，不！不我的洞！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/080.mp3`}),c[360]||=i(),c[361]||=a(`strong`,null,`Monica Geller:`,-1),c[362]||=i(` (screaming in pain) Ow!! Ow!!!`,-1),c[363]||=a(`blockquote`,null,[a(`p`,null,`（痛苦地尖叫）噢！！噢`)],-1),r(p,{src:`/audio/friends/S04/S04E01/081.mp3`}),c[364]||=i(),c[365]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[366]||=i(` (climbing out of the hole) What?! What?!! What is it?!`,-1),c[367]||=a(`blockquote`,null,[a(`p`,null,`（从洞里爬出来）什么？！什么？！！它是什么？！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/082.mp3`}),c[368]||=i(),c[369]||=a(`strong`,null,`Monica Geller:`,-1),c[370]||=i(` Jellyfish sting! Oh, it hurts! It hurts!! It hurts!!`,-1),c[371]||=a(`blockquote`,null,[a(`p`,null,`水母刺！哦，疼！很痛！！很痛！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/083.mp3`}),c[372]||=i(),c[373]||=a(`strong`,null,`Chandler Bing:`,-1),c[374]||=i(` Well, can we help?! You want us to take you back to the house?!`,-1),c[375]||=a(`blockquote`,null,[a(`p`,null,`我们能帮忙吗？！你想让我们带你回家？！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/084.mp3`}),c[376]||=i(),c[377]||=a(`strong`,null,`Monica Geller:`,-1),c[378]||=i(` It’s like two miles!`,-1),c[379]||=a(`blockquote`,null,[a(`p`,null,`好像有两英里！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/085.mp3`}),c[380]||=i(),c[381]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[382]||=i(` Yeah, and I’m a little tired from digging the hole.`,-1),c[383]||=a(`blockquote`,null,[a(`p`,null,`是啊，我挖这个洞有点累了。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/086.mp3`}),c[384]||=i(),c[385]||=a(`strong`,null,`Monica Geller:`,-1),c[386]||=i(` Oh damn the jellyfish. Damn all the jellyfish!`,-1),c[387]||=a(`blockquote`,null,[a(`p`,null,`哦，该死的水母。该死的水母！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/087.mp3`}),c[388]||=i(),c[389]||=a(`strong`,null,`Chandler Bing:`,-1),c[390]||=i(` We’ve got to do something!`,-1),c[391]||=a(`blockquote`,null,[a(`p`,null,`我们得做点什么！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/088.mp3`}),c[392]||=i(),c[393]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[394]||=i(` Well, there’s really only one thing you can do.`,-1),c[395]||=a(`blockquote`,null,[a(`p`,null,`嗯，你只能做一件事。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/089.mp3`}),c[396]||=i(),c[397]||=a(`strong`,null,`Monica Geller:`,-1),c[398]||=i(` What?! What is it?!`,-1),c[399]||=a(`blockquote`,null,[a(`p`,null,`什么？！它是什么？！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/090.mp3`}),c[400]||=i(),c[401]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[402]||=i(` You’re gonna have to pee on it.`,-1),c[403]||=a(`blockquote`,null,[a(`p`,null,`你得在上面撒尿。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/091.mp3`}),c[404]||=i(),c[405]||=a(`strong`,null,`Monica Geller:`,-1),c[406]||=i(` What?!! Gross!!`,-1),c[407]||=a(`blockquote`,null,[a(`p`,null,`什么？！！真恶心！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/092.mp3`}),c[408]||=i(),c[409]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[410]||=i(` Don’t blame me, I saw it on The Discovery Channel.`,-1),c[411]||=a(`blockquote`,null,[a(`p`,null,`别怪我，我在探索频道看到的。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/093.mp3`}),c[412]||=i(),c[413]||=a(`strong`,null,`Chandler Bing:`,-1),c[414]||=i(` Y'know what, he’s right. There’s something like uh, ammonia in that, that like kills the pain.`,-1),c[415]||=a(`blockquote`,null,[a(`p`,null,`你知道吗，他是对的。里面有氨水之类的东西，可以止痛。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/094.mp3`}),c[416]||=i(),c[417]||=a(`strong`,null,`Monica Geller:`,-1),c[418]||=i(` Well forget it! It doesn’t hurt that (tries to take a step) baaad!!!!`,-1),c[419]||=a(`blockquote`,null,[a(`p`,null,`算了吧！（试着迈出一步）巴阿德（baaad）！！！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/095.mp3`}),c[420]||=i(),c[421]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[422]||=i(` If you want some privacy you can use my hole.`,-1),c[423]||=a(`blockquote`,null,[a(`p`,null,`如果你想要一些隐私，你可以用我的洞。`)],-1),c[424]||=a(`hr`,null,null,-1),c[425]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The beach house, Phoebe is coming down the stairs all packed and ready to go.`)],-1),c[426]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`海滩小屋，菲比正从楼梯上走下来，满身行装，准备出发。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/096.mp3`}),c[427]||=i(),c[428]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[429]||=i(` Well, I’m ready to get the hell out of here! (Sees Ross and Rachel cuddling on the couch.) Oh. Are you? Are you?!! (they nod ‘Yes.’) Ohh! That’s so great!! Ooh, not for Bonnie. (they nod ‘No.’) But for you, yay! Ohh.`,-1),c[430]||=a(`blockquote`,null,[a(`p`,null,`嗯，我准备好离开这里了！（看到罗斯和瑞秋依偎在沙发上）哦。你是吗？你是吗？！！（他们点头“是的”。）哦！太棒了！！哦，不是给邦妮的。（他们点头“不”。）但是为了你，耶！哦。`)],-1),c[431]||=a(`p`,null,[a(`em`,null,`(The rest of the gang arrives with their heads down in shame.)`)],-1),c[432]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（该团伙的其他成员到达时羞愧地低下了头。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/097.mp3`}),c[433]||=i(),c[434]||=a(`strong`,null,`Ross Geller:`,-1),c[435]||=i(` Hey!`,-1),c[436]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/098.mp3`}),c[437]||=i(),c[438]||=a(`strong`,null,`Rachel Green:`,-1),c[439]||=i(` How was the beach?`,-1),c[440]||=a(`blockquote`,null,[a(`p`,null,`海滩怎么样？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/099.mp3`}),c[441]||=i(),c[442]||=a(`strong`,null,`Monica Geller:`,-1),c[443]||=i(` Nothing, I don’t know.`,-1),c[444]||=a(`blockquote`,null,[a(`p`,null,`没什么，我不知道。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/100.mp3`}),c[445]||=i(),c[446]||=a(`strong`,null,`Ross Geller:`,-1),c[447]||=i(` What happened?`,-1),c[448]||=a(`blockquote`,null,[a(`p`,null,`发生什么事了？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/101.mp3`}),c[449]||=i(),c[450]||=a(`strong`,null,`Monica Geller:`,-1),c[451]||=i(` Nothing. I’m gonna take a shower.`,-1),c[452]||=a(`blockquote`,null,[a(`p`,null,`没什么。我要洗个澡。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/102.mp3`}),c[453]||=i(),c[454]||=a(`strong`,null,`Chandler Bing:`,-1),c[455]||=i(` Me too!!`,-1),c[456]||=a(`blockquote`,null,[a(`p`,null,`我也是！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/103.mp3`}),c[457]||=i(),c[458]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[459]||=i(` Me too.`,-1),c[460]||=a(`blockquote`,null,[a(`p`,null,`我也是。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/104.mp3`}),c[461]||=i(),c[462]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[463]||=i(` Okay, I’m gonna put this (her suitcase) in the car.`,-1),c[464]||=a(`blockquote`,null,[a(`p`,null,`好吧，我要把这个（她的手提箱）放进车里。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/105.mp3`}),c[465]||=i(),c[466]||=a(`strong`,null,`Rachel Green:`,-1),c[467]||=i(` Ooh, I have to go pack. (Gets up to do so.) It really does?`,-1),c[468]||=a(`blockquote`,null,[a(`p`,null,`哦，我得收拾行李了。（站起来）真的吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/106.mp3`}),c[469]||=i(),c[470]||=a(`strong`,null,`Ross Geller:`,-1),c[471]||=i(` It does. It really and truly does.`,-1),c[472]||=a(`blockquote`,null,[a(`p`,null,`是的。确实如此。`)],-1),c[473]||=a(`p`,null,[a(`em`,null,`(Rachel kisses him, and goes upstairs. After she’s gone, Ross frantically tries to find and read the ‘Does it?’ part.)`)],-1),c[474]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（瑞秋吻了吻他，然后上楼。在她走后，罗斯疯狂地试图找到并阅读“是吗？”部分。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/107.mp3`}),c[475]||=t(` <strong>Ross Geller:</strong> (finding the part) (looks up in disgust) It so does not!!!<blockquote><p>（找到那个角色）（厌恶地抬起头）它不是这样的！！！</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Central Perk, Ross is telling Joey and Chandler about the letter.</em></p><blockquote><p>🎬 <em>中央公园，罗斯告诉乔伊和钱德勒这封信的事。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S04/S04E01/108.mp3`}),c[476]||=i(),c[477]||=a(`strong`,null,`Ross Geller:`,-1),c[478]||=i(` She wants me to take responsibility for everything that went wrong in our relationship. I mean she goes on for five pages about, about how I was unfaithful to her! (Both Joey and Chandler shrug their shoulders as to say ”Well...”) (yelling) WE WERE ON A BREAK!!!!!`,-1),c[479]||=a(`blockquote`,null,[a(`p`,null,`她要我为我们关系中的每一件事负责。我的意思是她写了五页关于我是如何对她不忠的！（乔伊和钱德勒都耸耸肩说“好吧……”）（大叫）我们休息了！！！！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/109.mp3`}),c[480]||=i(),c[481]||=a(`strong`,null,`Chandler Bing:`,-1),c[482]||=i(` Oh my God! If you say that one more time, I’m gonna break up with you!`,-1),c[483]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天啊！如果你再说一遍，我就和你分手！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/110.mp3`}),c[484]||=i(),c[485]||=a(`strong`,null,`Ross Geller:`,-1),c[486]||=i(` Fine! Fine! But this break-up was not all my fault, and she, she says here, (reading from the letter) “If you accept full responsibility...” (to Chandler and Joey) Full responsibility! “...I can begin to trust you again. Does that seem like something you can do. (yells at Joey) Does it?!!”`,-1),c[487]||=a(`blockquote`,null,[a(`p`,null,`很好！好的但这次分手不全是我的错，她在这里说，（从信中读到）“如果你承担全部责任……”（对钱德勒和乔伊）承担全部责任！“…我可以再次开始信任你了。这看起来像是你能做的事吗？（对乔伊大叫）是吗？！”`)],-1),r(p,{src:`/audio/friends/S04/S04E01/111.mp3`}),c[488]||=i(),c[489]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[490]||=i(` No?`,-1),c[491]||=a(`blockquote`,null,[a(`p`,null,`没有？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/112.mp3`}),c[492]||=i(),c[493]||=a(`strong`,null,`Chandler Bing:`,-1),c[494]||=i(` Look, Ross, you have what you want, you’re back with Rachel. If you bring this up now you’re gonna wreck the best thing that even happened to you.`,-1),c[495]||=a(`blockquote`,null,[a(`p`,null,`听着，罗斯，你得到了你想要的，你和瑞秋回来了。如果你现在提起这件事，你会毁掉发生在你身上最好的事情。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/113.mp3`}),c[496]||=i(),c[497]||=a(`strong`,null,`Ross Geller:`,-1),c[498]||=i(` (calming down) Yeah, I know. I mean, no, you’re right. Yeah I guess I’ll let it go. But you-you understand how-how hard it is to forget about this.`,-1),c[499]||=a(`blockquote`,null,[a(`p`,null,`（平静下来）是的，我知道。我是说，不，你是对的。是的，我想我会放手的。但你知道忘记这件事有多难。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/114.mp3`}),c[500]||=i(),c[501]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[502]||=i(` Sure, it’s hard to forget! But that doesn’t mean you have to talk about it! A lot of things happened on that trip that we should never, (to Chandler) ever talk about.`,-1),c[503]||=a(`blockquote`,null,[a(`p`,null,`当然，很难忘记！但这并不意味着你必须谈论它！在那次旅行中发生了很多我们永远不应该（对钱德勒）谈论的事情。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/115.mp3`}),c[504]||=i(),c[505]||=a(`strong`,null,`Ross Geller:`,-1),c[506]||=i(` What the hell happened on that beach?!`,-1),c[507]||=a(`blockquote`,null,[a(`p`,null,`那个海滩到底发生了什么？！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/116.mp3`}),c[508]||=t(` <strong>Joey Tribbiani:</strong> It’s between us and the sea, Ross!<blockquote><p>在我们和大海之间，罗斯！</p></blockquote><p><em>(Ross laughs and has a ‘Come on...’ look on his face as he looks and Chandler who nods his head in agreement with Joey. Ross is stunned.)</em></p><blockquote><p><em>（罗斯笑了笑，脸上带着一种“来吧…”的表情，钱德勒点头表示同意乔伊的看法。罗斯惊呆了。）</em></p></blockquote><hr><p>🎬 <em>A hallway in an apartment building. Phoebe is knocks on a door and it opens.</em></p><blockquote><p>🎬 <em>公寓楼的走廊。菲比正在敲门，门打开了。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S04/S04E01/117.mp3`}),c[509]||=i(),c[510]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[511]||=i(` (to the person that answered the door) Hi, Ursula.`,-1),c[512]||=a(`blockquote`,null,[a(`p`,null,`（对开门的人）嗨，乌苏拉。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/118.mp3`}),c[513]||=i(),c[514]||=a(`strong`,null,`Ursula:`,-1),c[515]||=i(` Hey!`,-1),c[516]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/119.mp3`}),c[517]||=i(),c[518]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[519]||=i(` Okay, well umm, I know that we haven’t talked in a long time, but umm okay, our Mom is not our birth Mom. This-this other lady is our birth Mom.`,-1),c[520]||=a(`blockquote`,null,[a(`p`,null,`好吧，嗯，我知道我们很久没谈过了，但嗯，好吧，我们的妈妈不是我们的生母。这位女士是我们的生母。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/120.mp3`}),c[521]||=i(),c[522]||=a(`strong`,null,`Ursula:`,-1),c[523]||=i(` Right, okay, the one that lives in Montuak, umm-hmm.`,-1),c[524]||=a(`blockquote`,null,[a(`p`,null,`对，好吧，住在蒙图阿克的那个，嗯哼。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/121.mp3`}),c[525]||=i(),c[526]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[527]||=i(` (shocked) You know her?!`,-1),c[528]||=a(`blockquote`,null,[a(`p`,null,`（震惊）你认识她？！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/122.mp3`}),c[529]||=i(),c[530]||=a(`strong`,null,`Ursula:`,-1),c[531]||=i(` No, I umm, I read about her in Mom’s suicide note.`,-1),c[532]||=a(`blockquote`,null,[a(`p`,null,`不，我，嗯，我在妈妈的遗书上读到过她。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/123.mp3`}),c[533]||=i(),c[534]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[535]||=i(` There-there was a suicide note?! (Ursula nods ‘Yes.’) Well, do you still have it?`,-1),c[536]||=a(`blockquote`,null,[a(`p`,null,`有一张遗书？！（乌苏拉点头“是的”。）好吧，你还有吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/124.mp3`}),c[537]||=i(),c[538]||=a(`strong`,null,`Ursula:`,-1),c[539]||=i(` (disgusted) Hang on. (She goes into her apartment and slams the door in Phoebe’s face.)`,-1),c[540]||=a(`blockquote`,null,[a(`p`,null,`（厌恶地）等一下。（她走进公寓，砰的一声关上菲比的脸。）`)],-1),r(p,{src:`/audio/friends/S04/S04E01/125.mp3`}),c[541]||=i(),c[542]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[543]||=i(` I can’t believe you didn’t tell me there was a suicide note!`,-1),c[544]||=a(`blockquote`,null,[a(`p`,null,`我不敢相信你没有告诉我有一张自杀纸条！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/126.mp3`}),c[545]||=i(),c[546]||=a(`strong`,null,`Ursula:`,-1),c[547]||=i(` Yeah. So how have you been doing?`,-1),c[548]||=a(`blockquote`,null,[a(`p`,null,`是的。你最近怎么样？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/127.mp3`}),c[549]||=i(),c[550]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[551]||=i(` I, umm, shut up!`,-1),c[552]||=a(`blockquote`,null,[a(`p`,null,`我，嗯，闭嘴！`)],-1),c[553]||=a(`p`,null,[a(`em`,null,`(Ursula opens the door and hands her the note.)`)],-1),c[554]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乌苏拉打开门，递给她纸条。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/128.mp3`}),c[555]||=i(),c[556]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[557]||=i(` (reading from the note) “Good-bye Phoebe and Ursula. I’ll miss you. P.S. Your Mom lives in Montauk.” You just wrote this!`,-1),c[558]||=a(`blockquote`,null,[a(`p`,null,`（读纸条）“再见，菲比和乌苏拉。我会想你的。还有，你妈妈住在蒙托克。”这是你写的！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/129.mp3`}),c[559]||=i(),c[560]||=a(`strong`,null,`Ursula:`,-1),c[561]||=i(` Well, it’s pretty much the gist. Well, except for the poem. You read the poem, right?`,-1),c[562]||=a(`blockquote`,null,[a(`p`,null,`嗯，这差不多就是要点。嗯，除了那首诗。你读过这首诗，对吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/130.mp3`}),c[563]||=i(),c[564]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[565]||=i(` Noooo!!`,-1),c[566]||=a(`blockquote`,null,[a(`p`,null,`不！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/131.mp3`}),c[567]||=i(),c[568]||=a(`strong`,null,`Ursula:`,-1),c[569]||=i(` All right, hang on! (She takes the note, goes back into her apartment and slams the door shut.)`,-1),c[570]||=a(`blockquote`,null,[a(`p`,null,`好的，等一下！（她记下便条，回到公寓，砰地关上门。）`)],-1),c[571]||=a(`hr`,null,null,-1),c[572]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's, Chandler, Monica, and Joey are sitting at the table eating dinner and not talking. Ross and Rachel are outside cuddling on the balcony.`)],-1),c[573]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋家、钱德勒、莫妮卡和乔伊坐在桌旁吃晚饭，不说话。罗斯和瑞秋在阳台上搂抱着。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/132.mp3`}),c[574]||=i(),c[575]||=a(`strong`,null,`Monica Geller:`,-1),c[576]||=i(` Pass the cheese, please.`,-1),c[577]||=a(`blockquote`,null,[a(`p`,null,`请把奶酪递给我。`)],-1),c[578]||=a(`p`,null,[a(`em`,null,`(Joey hands her the cheese without looking at her.)`)],-1),c[579]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乔伊没有看她一眼就把奶酪递给她。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/133.mp3`}),c[580]||=i(),c[581]||=a(`strong`,null,`Monica Geller:`,-1),c[582]||=i(` My God, you can’t even look at me! Can you?`,-1),c[583]||=a(`blockquote`,null,[a(`p`,null,`天哪，你连看都不敢看我！你能？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/134.mp3`}),c[584]||=i(),c[585]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[586]||=i(` Nope.`,-1),c[587]||=a(`blockquote`,null,[a(`p`,null,`没有。`)],-1),c[588]||=a(`p`,null,[a(`em`,null,`(Phoebe enters.)`)],-1),c[589]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（菲比进来了。）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/135.mp3`}),c[590]||=i(),c[591]||=a(`strong`,null,`Chandler Bing:`,-1),c[592]||=i(` (jumping up) Hey! Phoebe! We can talk to Phoebe!!`,-1),c[593]||=a(`blockquote`,null,[a(`p`,null,`（跳起来）嘿！菲比！我们可以和菲比谈谈！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/136.mp3`}),c[594]||=i(),c[595]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[596]||=i(` No. I’m-I’m to depressed to talk.`,-1),c[597]||=a(`blockquote`,null,[a(`p`,null,`不，我-我很沮丧不能说话。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/137.mp3`}),c[598]||=i(),c[599]||=a(`strong`,null,`Chandler Bing:`,-1),c[600]||=i(` I’ll give you a thousand dollars to talk to us.`,-1),c[601]||=a(`blockquote`,null,[a(`p`,null,`我给你一千美元和我们谈谈。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/138.mp3`}),c[602]||=i(),c[603]||=a(`strong`,null,`Ross Geller:`,-1),c[604]||=i(` (coming back in with Rachel) Hey, you guys! What do you, what do you think about making that beach trip an annual thing?`,-1),c[605]||=a(`blockquote`,null,[a(`p`,null,`（和瑞秋一起回来）嘿，你们！你，你觉得每年去海滩旅游怎么样？`)],-1),c[606]||=a(`p`,null,`Chandler, Monica, and **Joey Tribbiani: **NO!!!`,-1),c[607]||=a(`blockquote`,null,[a(`p`,null,[i(`钱德勒、莫妮卡和`),a(`strong`,null,`乔伊·崔比安尼：`),i(`不！！！`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/139.mp3`}),c[608]||=i(),c[609]||=a(`strong`,null,`Rachel Green:`,-1),c[610]||=i(` All right, that’s it, you guys! What happened out there?`,-1),c[611]||=a(`blockquote`,null,[a(`p`,null,`好了，就这样，你们！外面发生了什么事？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/140.mp3`}),c[612]||=i(),c[613]||=a(`strong`,null,`Monica Geller:`,-1),c[614]||=i(` What? We took a walk, nothing happened. I can back with nothing all over me.`,-1),c[615]||=a(`blockquote`,null,[a(`p`,null,`什么？我们散步，什么事也没发生。我身上没什么东西就可以回来了。`)],-1),c[616]||=a(`p`,null,`Ross and **Rachel Green: **Come on!`,-1),c[617]||=a(`blockquote`,null,[a(`p`,null,[i(`罗斯和`),a(`strong`,null,`瑞秋·格林：`),i(`来吧！`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/141.mp3`}),c[618]||=i(),c[619]||=a(`strong`,null,`Ross Geller:`,-1),c[620]||=i(` What happened? Joey?`,-1),c[621]||=a(`blockquote`,null,[a(`p`,null,`发生什么事了？乔伊？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/142.mp3`}),c[622]||=i(),c[623]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[624]||=i(` All right. (gets up)`,-1),c[625]||=a(`blockquote`,null,[a(`p`,null,`好的。（站起来）`)],-1),r(p,{src:`/audio/friends/S04/S04E01/143.mp3`}),c[626]||=i(),c[627]||=a(`strong`,null,`Monica Geller:`,-1),c[628]||=i(` (stopping him) No! Joey, we swore we’d never tell!`,-1),c[629]||=a(`blockquote`,null,[a(`p`,null,`（阻止他）不！乔伊，我们发誓永远不会告诉你！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/144.mp3`}),c[630]||=i(),c[631]||=a(`strong`,null,`Chandler Bing:`,-1),c[632]||=i(` (running over and joining Monica) They’ll never understand!`,-1),c[633]||=a(`blockquote`,null,[a(`p`,null,`（跑过去加入莫妮卡）他们永远不会明白！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/145.mp3`}),c[634]||=i(),c[635]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[636]||=i(` Well, we have to say something! We have to get it out! It’s eating me alive!! Monica got stung by a jellyfish.`,-1),c[637]||=a(`blockquote`,null,[a(`p`,null,`嗯，我们得说点什么！我们必须把它弄出来！它把我活活吃掉了！！莫妮卡被水母蜇了。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/146.mp3`}),c[638]||=i(),c[639]||=a(`strong`,null,`Monica Geller:`,-1),c[640]||=i(` (interrupting) All right!! All right. (walks slowly into the living room) I got stung. Stung bad. I couldn’t stand. I-I couldn’t walk.`,-1),c[641]||=a(`blockquote`,null,[a(`p`,null,`（打断）好吧！！好吧（慢慢走进客厅）我被蛰了。刺痛得厉害。我受不了了。我不能走路。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/147.mp3`}),c[642]||=i(),c[643]||=a(`strong`,null,`Chandler Bing:`,-1),c[644]||=i(` (following Monica) We were two miles from the house. Scared and alone. We didn’t think we could make it. (He goes to put his hands on Monica’s shoulders but for some reason can quite complete the action and pulls back.)`,-1),c[645]||=a(`blockquote`,null,[a(`p`,null,`（跟着莫妮卡）我们离房子有两英里远。害怕和孤独。我们认为我们做不到。（他将手放在莫妮卡的肩膀上，但由于某种原因，他完全可以完成动作并向后拉。）`)],-1),r(p,{src:`/audio/friends/S04/S04E01/148.mp3`}),c[646]||=i(),c[647]||=a(`strong`,null,`Monica Geller:`,-1),c[648]||=i(` I was in too much pain.`,-1),c[649]||=a(`blockquote`,null,[a(`p`,null,`我太痛苦了。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/149.mp3`}),c[650]||=i(),c[651]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[652]||=i(` And I was tired from digging the huge hole!`,-1),c[653]||=a(`blockquote`,null,[a(`p`,null,`挖了这么大的洞，我都累了！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/150.mp3`}),c[654]||=i(),c[655]||=a(`strong`,null,`Chandler Bing:`,-1),c[656]||=i(` And then Joey remembered something.`,-1),c[657]||=a(`blockquote`,null,[a(`p`,null,`然后乔伊想起了一些事。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/151.mp3`}),c[658]||=i(),c[659]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[660]||=i(` I’d seen this thing on The Discovery Channel...`,-1),c[661]||=a(`blockquote`,null,[a(`p`,null,`我在探索频道看到过这件事。。。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/152.mp3`}),c[662]||=i(),c[663]||=a(`strong`,null,`Ross Geller:`,-1),c[664]||=i(` Wait a minute! I saw that! On The Discovery Channel, yeah! About jellyfish and how if you... (stops suddenly and turns to look at Monica) Ewwww!! You peed on yourself?!`,-1),c[665]||=a(`blockquote`,null,[a(`p`,null,`等一下！我看见了！在探索频道，是的！关于水母，如果你。。。（突然停下来，转身看着莫妮卡）哇！！你在自己身上撒尿？！`)],-1),c[666]||=a(`p`,null,`Phoebe and **Rachel Green: **Ewwww!!`,-1),c[667]||=a(`blockquote`,null,[a(`p`,null,[i(`菲比和`),a(`strong`,null,`瑞秋·格林：`),i(`哇！！`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/153.mp3`}),c[668]||=i(),c[669]||=a(`strong`,null,`Monica Geller:`,-1),c[670]||=i(` You can’t say that!! You-you don’t know!! I mean I thought I was gonna pass out from the pain! Anyway I-I tried, but I-I couldn’t...bend that way. So... (looks at Joey.)`,-1),c[671]||=a(`blockquote`,null,[a(`p`,null,`你不能这么说！！你不知道！！我是说我以为我会因为疼痛而昏倒！不管怎么说，我试过了，但我…我不能那样弯曲。所以（看着乔伊。）`)],-1),c[672]||=a(`p`,null,`Phoebe, Ross, and **Rachel Green: **(turning to look at Joey) Ewwww!!`,-1),c[673]||=a(`blockquote`,null,[a(`p`,null,[i(`菲比、罗斯和`),a(`strong`,null,`瑞秋·格林：`),i(`（转过身来看着乔伊）哇！！`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/154.mp3`}),c[674]||=i(),c[675]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[676]||=i(` That’s right I stepped up! She’s my friend and she needed help! And if I had too, I’d pee on anyone of you! Only, uhh, I couldn’t. I got the stage fright. I wanted to help, but there was too much pressure. So-so I uh, I turned to Chandler.`,-1),c[677]||=a(`blockquote`,null,[a(`p`,null,`是的，我加快了脚步！她是我的朋友，她需要帮助！如果我也有，我会在你们任何人身上撒尿！只是，嗯，我不能。我怯场了。我想帮忙，但压力太大了。所以我，呃，我转向钱德勒。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/155.mp3`}),c[678]||=i(),c[679]||=a(`strong`,null,`Chandler Bing:`,-1),c[680]||=i(` (wails loudly into his hands) Joey kept screaming at me, “Do it now! Do it!! Do it! Do it now!!” Sometimes late at night I can still here the screaming.`,-1),c[681]||=a(`blockquote`,null,[a(`p`,null,`（用手大声哭）乔伊不停地对我尖叫，“现在就做！现在就做！！现在就做！！”有时深夜我还能听到尖叫声。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/156.mp3`}),c[682]||=i(),c[683]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[684]||=i(` (laughs) That’s ‘cause sometimes I just do it through my wall to freak you out.`,-1),c[685]||=a(`blockquote`,null,[a(`p`,null,`（笑）那是因为有时候我只是穿过墙来吓唬你。`)],-1),c[686]||=a(`hr`,null,null,-1),c[687]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Central Perk, Phoebe is finishing up a song.`)],-1),c[688]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`中央公园，菲比正在完成一首歌。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/157.mp3`}),c[689]||=i(),c[690]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[691]||=i(` (singing) “...fuchsia and mauvvve. Those are the 66 colours of my bedroommmm.” (applause) Thank you, thank you. Ohh, and I invite you to count the colours in your bedroom. (Sees that Phoebe Sr. has entered, and to her) Except for you. You go away.`,-1),c[692]||=a(`blockquote`,null,[a(`p`,null,`（唱）“……紫红色和紫红色。这是我卧室的66种颜色。”（掌声）谢谢，谢谢。哦，我邀请你数一数卧室里的颜色。（看到老菲比进来了，对她说）除了你。你走开。`)],-1),c[693]||=a(`p`,null,`Phoebe Sr.: I’ll go in a second, I-I just wanted to tell you that there hasn’t been a day where I didn’t regret giving you up.`,-1),c[694]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`我马上就去，我只是想告诉你，我没有一天不后悔放弃你。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/158.mp3`}),c[695]||=i(),c[696]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[697]||=i(` Okay, bye.`,-1),c[698]||=a(`blockquote`,null,[a(`p`,null,`好的，再见。`)],-1),c[699]||=a(`p`,null,`Phoebe Sr.: No, I’m not done. I-I-I just want you to know that I, the reason I didn’t look you up was, well I was afraid that you’d react, just well like, the way, the way you’re reacting right now, and can’t we just, y'know, start from here?`,-1),c[700]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`不，我还没做完。我，我，我只是想让你知道，我，我没有去找你的原因是，我害怕你会做出反应，就像，你现在的反应，我们不能，你知道，从这里开始吗？`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/159.mp3`}),c[701]||=i(),c[702]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[703]||=i(` No.`,-1),c[704]||=a(`blockquote`,null,[a(`p`,null,`没有。`)],-1),c[705]||=a(`p`,null,`Phoebe Sr.: Sorry. But just one last thing. Y'know you came looking for family. I’m family, I’m it. Now, now I’m done. (starts to leave)`,-1),c[706]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`对不起。但最后一件事。你知道你是来找家人的。我是家人，我就是它。现在，现在我做完了。（开始离开）`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/160.mp3`}),c[707]||=i(),c[708]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[709]||=i(` But, it’s not like we’re losing anything. Y'know?`,-1),c[710]||=a(`blockquote`,null,[a(`p`,null,`但是，我们并没有失去任何东西。你知道吗？`)],-1),c[711]||=a(`p`,null,`Phoebe Sr.: Yeah, I guess you’re right.`,-1),c[712]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`是的，我想你是对的。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/161.mp3`}),c[713]||=i(),c[714]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[715]||=i(` It’s not like we-we know each other or anything. Or that have anything in common.`,-1),c[716]||=a(`blockquote`,null,[a(`p`,null,`我们又不是互相认识的。或者有任何共同之处。`)],-1),c[717]||=a(`p`,null,`Phoebe Sr.: Well, I don’t know. I mean it’s not like we don’t have anything in common. I mean I like uh, pizza.`,-1),c[718]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`嗯，我不知道。我的意思是我们并不是没有共同点。我是说我喜欢披萨。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/162.mp3`}),c[719]||=i(),c[720]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[721]||=i(` I-I like pizza!`,-1),c[722]||=a(`blockquote`,null,[a(`p`,null,`我喜欢比萨饼！`)],-1),c[723]||=a(`p`,null,`Phoebe Sr.: You do?! Wait, I like umm, the Beetles.`,-1),c[724]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`是吗？！等等，我喜欢甲虫。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/163.mp3`}),c[725]||=i(),c[726]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[727]||=i(` Oh my God, so do I!`,-1),c[728]||=a(`blockquote`,null,[a(`p`,null,`哦，我的天，我也是！`)],-1),c[729]||=a(`p`,null,`Phoebe Sr.: I knew it, wow!!`,-1),c[730]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`我就知道，哇！！`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/164.mp3`}),c[731]||=i(),c[732]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[733]||=i(` Wait-wait-wait, wait! Puppies. Cute or ugly?`,-1),c[734]||=a(`blockquote`,null,[a(`p`,null,`等等，等等！小狗。可爱还是丑陋？`)],-1),c[735]||=a(`p`,null,`Phoebe Sr.: Ohh, so cute.`,-1),c[736]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`哦，太可爱了。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/165.mp3`}),c[737]||=i(),c[738]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[739]||=i(` Uh-huh, well! But umm, still I’m-I’m mad at you.`,-1),c[740]||=a(`blockquote`,null,[a(`p`,null,`嗯，嗯，嗯！但我还是生你的气。`)],-1),c[741]||=a(`p`,null,`Phoebe Sr.: I know. I’m mad at me too.`,-1),c[742]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`我知道。我也生我的气。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/166.mp3`}),c[743]||=i(),c[744]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[745]||=i(` Well umm, do you wanna get something to eat? I’m kinda hungry.`,-1),c[746]||=a(`blockquote`,null,[a(`p`,null,`嗯，你想吃点什么吗？我有点饿了。`)],-1),c[747]||=a(`p`,null,`Phoebe Sr.: Hey! Me too!`,-1),c[748]||=a(`blockquote`,null,[a(`p`,null,[i(`老`),a(`strong`,null,`菲比·布菲：`),i(`嘿！我也是！`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/167.mp3`}),c[749]||=i(),c[750]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[751]||=i(` All right, stop it. Now you’re just doing it to freak me out.`,-1),c[752]||=a(`blockquote`,null,[a(`p`,null,`好吧，停下来。现在你这么做只是为了吓唬我。`)],-1),c[753]||=a(`hr`,null,null,-1),c[754]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Rachel’s bedroom. Ross and Rachel have just finished consummating the new relationship.`)],-1),c[755]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`瑞秋的卧室。罗斯和瑞秋刚刚结束了新的关系。`)])],-1),r(p,{src:`/audio/friends/S04/S04E01/168.mp3`}),c[756]||=i(),c[757]||=a(`strong`,null,`Rachel Green:`,-1),c[758]||=i(` Oh-hooo, I missed you.`,-1),c[759]||=a(`blockquote`,null,[a(`p`,null,`哦，呼，我想你了。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/169.mp3`}),c[760]||=i(),c[761]||=a(`strong`,null,`Ross Geller:`,-1),c[762]||=i(` I missed you too.`,-1),c[763]||=a(`blockquote`,null,[a(`p`,null,`我也很想你。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/170.mp3`}),c[764]||=i(),c[765]||=a(`strong`,null,`Rachel Green:`,-1),c[766]||=i(` Ooh, I was soo nervous about that letter. But the way you owned up to everything, it just showed me how much you’ve grown. Y'know?`,-1),c[767]||=a(`blockquote`,null,[a(`p`,null,`哦，我对那封信太紧张了。但你承认一切的方式，让我知道你成长了多少。你知道吗？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/171.mp3`}),c[768]||=i(),c[769]||=a(`strong`,null,`Ross Geller:`,-1),c[770]||=i(` (getting miffed) I suppose.`,-1),c[771]||=a(`blockquote`,null,[a(`p`,null,`（生气了）我想是吧。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/172.mp3`}),c[772]||=i(),c[773]||=a(`strong`,null,`Rachel Green:`,-1),c[774]||=i(` You have! Ross, you should give yourself credit. I mean my Mom never thought this would work out. It was all, “Once a cheater, always a cheater.”`,-1),c[775]||=a(`blockquote`,null,[a(`p`,null,`你有！罗斯，你应该相信自己。我的意思是我妈妈从没想过这会成功。都是“曾经是骗子，永远是骗子。”`)],-1),r(p,{src:`/audio/friends/S04/S04E01/173.mp3`}),c[776]||=i(),c[777]||=a(`strong`,null,`Ross Geller:`,-1),c[778]||=i(` (getting angry) Umm-hmm.`,-1),c[779]||=a(`blockquote`,null,[a(`p`,null,`（生气）嗯哼。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/174.mp3`}),c[780]||=i(),c[781]||=a(`strong`,null,`Rachel Green:`,-1),c[782]||=i(` Ooh, I just wish we hadn’t lost those four months, but if time was what you needed just to gain a little perspective...`,-1),c[783]||=a(`blockquote`,null,[a(`p`,null,`哦，我只是希望我们没有失去那四个月，但是如果你需要时间来获得一点洞察力。。。`)],-1),c[784]||=a(`p`,null,`[cut to Monica cleaning the floor in the kitchen]`,-1),c[785]||=a(`blockquote`,null,[a(`p`,null,`[切到莫妮卡在厨房擦地板]`)],-1),r(p,{src:`/audio/friends/S04/S04E01/175.mp3`}),c[786]||=i(),c[787]||=a(`strong`,null,`Ross Geller:`,-1),c[788]||=i(` (yelling from the bedroom) WE WERE ON A BREAK!!!!!!!`,-1),c[789]||=a(`blockquote`,null,[a(`p`,null,`（从卧室里大叫）我们在休息！！！！！！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/176.mp3`}),c[790]||=i(),c[791]||=a(`strong`,null,`Chandler Bing:`,-1),c[792]||=i(` (entering with Joey) (to Monica) Coffee house?`,-1),c[793]||=a(`blockquote`,null,[a(`p`,null,`（和乔伊一起进入）（对莫妮卡）咖啡馆？`)],-1),r(p,{src:`/audio/friends/S04/S04E01/177.mp3`}),c[794]||=i(),c[795]||=a(`strong`,null,`Monica Geller:`,-1),c[796]||=i(` You bet.`,-1),c[797]||=a(`blockquote`,null,[a(`p`,null,`当然。`)],-1),c[798]||=a(`p`,null,`[cut back to Rachel’s bedroom with both of them hurriedly getting dressed]`,-1),c[799]||=a(`blockquote`,null,[a(`p`,null,`[切回瑞秋的卧室，他们两人匆忙穿好衣服]`)],-1),r(p,{src:`/audio/friends/S04/S04E01/178.mp3`}),c[800]||=i(),c[801]||=a(`strong`,null,`Ross Geller:`,-1),c[802]||=i(` And for the record, it took two people to break up this relationship!!`,-1),c[803]||=a(`blockquote`,null,[a(`p`,null,`我要说的是，两个人打破了这段关系！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/179.mp3`}),c[804]||=i(),c[805]||=a(`strong`,null,`Rachel Green:`,-1),c[806]||=i(` Yeah! You and that girl from that copy place, which yesterday you took full responsibility for!!`,-1),c[807]||=a(`blockquote`,null,[a(`p`,null,`是啊！你和那个复印处的女孩，昨天你承担了全部责任！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/180.mp3`}),c[808]||=i(),c[809]||=a(`strong`,null,`Ross Geller:`,-1),c[810]||=i(` I didn’t know what I was taking full responsibility for! Okay?! I didn’t finish the whole letter!`,-1),c[811]||=a(`blockquote`,null,[a(`p`,null,`我不知道我要对什么负全部责任！可以我没有写完整封信！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/181.mp3`}),c[812]||=i(),c[813]||=a(`strong`,null,`Rachel Green:`,-1),c[814]||=i(` What?!!`,-1),c[815]||=a(`blockquote`,null,[a(`p`,null,`什么？！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/182.mp3`}),c[816]||=i(),c[817]||=a(`strong`,null,`Ross Geller:`,-1),c[818]||=i(` I fell asleep!`,-1),c[819]||=a(`blockquote`,null,[a(`p`,null,`我睡着了！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/183.mp3`}),c[820]||=i(),c[821]||=a(`strong`,null,`Rachel Green:`,-1),c[822]||=i(` You fell asleep?!`,-1),c[823]||=a(`blockquote`,null,[a(`p`,null,`你睡着了？！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/184.mp3`}),c[824]||=i(),c[825]||=a(`strong`,null,`Ross Geller:`,-1),c[826]||=i(` It was 5:30 in the morning, and you had rambled on for 18 pages. Front and back!! (they go into the living room, trapping Monica, Chandler, and Joey in the kitchen) (to Rachel) Oh-oh-oh, and by the way, Y-O-U-apostrophe-R-E means ‘you are,’ Y-O-U-R means ‘your!’`,-1),c[827]||=a(`blockquote`,null,[a(`p`,null,`那是早上5:30，你已经漫无目的地讲了18页了。前面和后面！！（他们走进客厅，把莫妮卡、钱德勒和乔伊困在厨房里）（对瑞秋说）哦哦哦，顺便说一句，Y-O-U-撇号-R-E的意思是“你是”，Y-O-U-R的意思是“你的！”`)],-1),r(p,{src:`/audio/friends/S04/S04E01/185.mp3`}),c[828]||=i(),c[829]||=a(`strong`,null,`Rachel Green:`,-1),c[830]||=i(` Y'know I can’t believe I even thought about getting back together again! We are so over!!`,-1),c[831]||=a(`blockquote`,null,[a(`p`,null,`你知道吗，我简直不敢相信我甚至还想过要重归于好！我们结束了！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/186.mp3`}),c[832]||=i(),c[833]||=a(`strong`,null,`Ross Geller:`,-1),c[834]||=i(` (starts to cry) FINE BY ME!! (he opens the door and traps Chandler behind it)`,-1),c[835]||=a(`blockquote`,null,[a(`p`,null,`（开始哭）我很好！！（他打开门，把钱德勒困在门后）`)],-1),r(p,{src:`/audio/friends/S04/S04E01/187.mp3`}),c[836]||=i(),c[837]||=a(`strong`,null,`Rachel Green:`,-1),c[838]||=i(` Oh, oh, and hey-hey-hey, those little spelling tips will come in handy when you’re at home on Saturday nights playing Scrabble with Monica!!`,-1),c[839]||=a(`blockquote`,null,[a(`p`,null,`哦，哦，嘿，嘿，当你周六晚上在家和莫妮卡玩拼字游戏时，这些小拼写技巧会派上用场的！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/188.mp3`}),c[840]||=i(),c[841]||=a(`strong`,null,`Monica Geller:`,-1),c[842]||=i(` Hey!!`,-1),c[843]||=a(`blockquote`,null,[a(`p`,null,`嘿！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/189.mp3`}),c[844]||=i(),c[845]||=a(`strong`,null,`Rachel Green:`,-1),c[846]||=i(` (to Monica) Sorry!! (to Ross) I just feel bad about all that sleep you’re gonna miss wishing you were with me!`,-1),c[847]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）对不起！！（对罗斯）我只是觉得很难过，你会想念那些希望和我在一起的睡眠！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/190.mp3`}),c[848]||=i(),c[849]||=a(`strong`,null,`Ross Geller:`,-1),c[850]||=i(` Oh, no-no-no don’t you worry about me falling asleep. I still have your letter!!!`,-1),c[851]||=a(`blockquote`,null,[a(`p`,null,`哦，不，不，你不用担心我睡着了。我还有你的信！！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/191.mp3`}),c[852]||=i(),c[853]||=a(`strong`,null,`Rachel Green:`,-1),c[854]||=i(` And hey! Just so you know, it’s not that common! It doesn’t happen to every guy! And it is a big deal!!`,-1),c[855]||=a(`blockquote`,null,[a(`p`,null,`嘿！你要知道，这并不常见！不是每个人都会这样！这是一件大事！！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/192.mp3`}),c[856]||=t(` <strong>Chandler Bing:</strong> I KNEW IT!!!!<blockquote><p>我就知道！！！！</p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s, Chandler and Monica are playing cards at the dinner table.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋家，钱德勒和莫妮卡在餐桌上打牌。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S04/S04E01/193.mp3`}),c[857]||=i(),c[858]||=a(`strong`,null,`Monica Geller:`,-1),c[859]||=i(` (sets down some cards) Gin.`,-1),c[860]||=a(`blockquote`,null,[a(`p`,null,`（放下一些卡片）杜松子酒。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/194.mp3`}),c[861]||=i(),c[862]||=a(`strong`,null,`Chandler Bing:`,-1),c[863]||=i(` We were playing Gin? Y'know if we were a couple, we could play this game naked.`,-1),c[864]||=a(`blockquote`,null,[a(`p`,null,`我们在玩杜松子酒？如果我们是夫妻，我们可以裸体玩这个游戏。`)],-1),r(p,{src:`/audio/friends/S04/S04E01/195.mp3`}),c[865]||=i(),c[866]||=a(`strong`,null,`Monica Geller:`,-1),c[867]||=i(` Will you stop!`,-1),c[868]||=a(`blockquote`,null,[a(`p`,null,`你能停下来吗！`)],-1),r(p,{src:`/audio/friends/S04/S04E01/196.mp3`}),c[869]||=i(),c[870]||=a(`strong`,null,`Chandler Bing:`,-1),c[871]||=i(` Okay. All right.`,-1),c[872]||=a(`blockquote`,null,[a(`p`,null,`好的。好吧`)],-1),r(p,{src:`/audio/friends/S04/S04E01/197.mp3`}),c[873]||=i(),c[874]||=a(`strong`,null,`Monica Geller:`,-1),c[875]||=i(` Okay, all right, I think you’re great, I think you’re sweet, and you’re smart, and I love you. But you will always be the guy who peed on me.`,-1),c[876]||=a(`blockquote`,null,[a(`p`,null,`好吧，好吧，我觉得你很棒，我觉得你很可爱，你很聪明，我爱你。但你永远是那个在我身上撒尿的人。`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};